// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/0x93c32845fae42c83a70e5f06214c8433665c2ab5.sol";

contract TimestampVulnerabilityTest is Test {
    X_WALLET public wallet;
    Log public logInst;
    address user = makeAddr("user");

    function setUp() public {
        logInst = new Log();
        wallet = new X_WALLET(address(logInst));
        vm.deal(user, 10 ether);
    }

    // Test shows collection fails at exact unlock time
    function testCollectFailsAtExactUnlockTime() public {
        uint256 depositAmount = 1 ether;
        uint256 unlockTime = block.timestamp + 7 days;

        // Deposit funds
        vm.prank(user);
        wallet.Put{value: depositAmount}(unlockTime);

        // Advance to exact unlock time
        vm.warp(unlockTime);

        uint256 initialContractBalance = address(wallet).balance;
        uint256 initialUserBalance = user.balance;

        // Attempt withdrawal
        vm.prank(user);
        wallet.Collect(depositAmount);

        // Verify failed withdrawal
        assertEq(address(wallet).balance, initialContractBalance, "Funds withdrawn at exact unlock time");
        assertEq(user.balance, initialUserBalance, "Ether received at exact unlock time");
    }

    // Test shows successful collection after unlock time
    function testCollectSucceedsAfterUnlockTime() public {
        uint256 depositAmount = 1 ether;
        uint256 unlockTime = block.timestamp + 7 days;

        // Deposit funds
        vm.prank(user);
        wallet.Put{value: depositAmount}(unlockTime);

        // Advance to after unlock time
        vm.warp(unlockTime + 1 seconds);

        uint256 initialContractBalance = address(wallet).balance;
        uint256 initialUserBalance = user.balance;

        // Attempt withdrawal
        vm.prank(user);
        wallet.Collect(depositAmount);

        // Verify successful withdrawal
        assertEq(address(wallet).balance, initialContractBalance - depositAmount, "Withdrawal failed after unlock time");
        assertEq(user.balance, initialUserBalance + depositAmount, "Ether not received after unlock time");
    }

    // Test shows immediate withdrawal failure after deposit
    function testImmediateWithdrawalFailure() public {
        uint256 depositAmount = 1 ether;

        // Deposit with immediate unlock time
        vm.prank(user);
        wallet.Put{value: depositAmount}(0);

        // Record balances after deposit
        uint256 contractBalanceAfterDeposit = address(wallet).balance;
        uint256 userBalanceAfterDeposit = user.balance;

        // Attempt immediate withdrawal
        vm.prank(user);
        wallet.Collect(depositAmount);

        // Verify withdrawal failure
        assertEq(address(wallet).balance, contractBalanceAfterDeposit, "Immediate withdrawal succeeded");
        assertEq(user.balance, userBalanceAfterDeposit, "Ether received immediately after deposit");
    }
}
```
